'use strict';
const $=s=>document.querySelector(s), app=$('#app');
const {rounds, bank, sources} = syllabus;
const formats={choice:'Tap one answer',number:'Type a number',match:'Match the pairs',order:'Put in order',multi:'Pick two answers'};
let prefs={music:true,sound:true,length:'standard',readAuto:false};
try{prefs={...prefs,...JSON.parse(localStorage.getItem('retail-prefs')||'{}')}}catch{}
if(prefs.short && prefs.length==='standard')prefs.length='short';
if(!['short','standard','full'].includes(prefs.length))prefs.length='standard';
let state=null, current=null, selected=[],matched=[], matchLeft=null, wrong=0, usedHint=false, resolved=false, outcomes=[], bonus=0, spun=false, spinning=false;
const money=t=>String(t), esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const text=s=>esc(money(s));
function savePrefs(){try{localStorage.setItem('retail-prefs',JSON.stringify(prefs))}catch{}updateAudioButtons()}
function say(s){$('#announce').textContent='';setTimeout(()=>$('#announce').textContent=money(s),30)}
function goTop(){window.scrollTo({top:0,behavior:'instant'})}
function bind(id,fn){document.getElementById(id)?.addEventListener('click',fn)}
let ctx,musicGain,musicTimer,beat=0;let speechDucked=false;
function initAudio(){try{ctx ||= new (window.AudioContext||window.webkitAudioContext)();if(!musicGain){musicGain=ctx.createGain();musicGain.connect(ctx.destination)}ctx.resume();syncMusic()}catch{}}
function tone(freq,when,duration,gain=.08,type='sine',dest){if(!ctx)return;const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.value=freq;o.connect(g);g.connect(dest||ctx.destination);g.gain.setValueAtTime(0,when);g.gain.linearRampToValueAtTime(gain,when+.015);g.gain.exponentialRampToValueAtTime(.001,when+duration);o.start(when);o.stop(when+duration+.02)}
function syncMusic(){if(!ctx)return;const on=prefs.music&&!document.hidden;musicGain.gain.setTargetAtTime(on?(speechDucked?.15:.48):0,ctx.currentTime,.1);if(on&&!musicTimer){musicTimer=setInterval(()=>{const melody=[523.25,659.25,783.99,659.25,587.33,698.46,880,698.46,523.25,659.25,783.99,987.77,880,783.99,659.25,587.33];tone(melody[beat%16],ctx.currentTime,.25,.07,'sine',musicGain);if(beat%2===0)tone([130.81,146.83,130.81,164.81][Math.floor(beat/4)%4],ctx.currentTime,.38,.08,'triangle',musicGain);beat++},360)}if(!on&&musicTimer){clearInterval(musicTimer);musicTimer=null}}
function sfx(correct){if(!prefs.sound)return;initAudio();if(!ctx)return;const now=ctx.currentTime;(correct?[523.25,659.25,783.99]:[293.66,261.63]).forEach((n,i)=>tone(n,now+i*.12,.23,correct?.09:.07,'sine'))}
function updateAudioButtons(){$('#music').setAttribute('aria-pressed',prefs.music);$('#music').innerHTML=`♫ <span>Music ${prefs.music?'on':'off'}</span>`;$('#sound').setAttribute('aria-pressed',prefs.sound);$('#sound').innerHTML=`◖♪ <span>Sound ${prefs.sound?'on':'off'}</span>`}
function stopSpeech(){if('speechSynthesis'in window)speechSynthesis.cancel();speechDucked=false;syncMusic()}
function read(s){if(!('speechSynthesis'in window)){say('Read aloud is not available in this browser.');return}stopSpeech();const u=new SpeechSynthesisUtterance(money(s).replaceAll('|',', ').replaceAll('−',' minus ').replaceAll('▥','barcode scanner'));u.lang='en-GB';u.rate=.82;speechDucked=true;syncMusic();u.onend=u.onerror=()=>{speechDucked=false;syncMusic()};speechSynthesis.speak(u)}
function questionSpeech(){return current.title+'. '+current.instruction+'. '+(current.product?current.product+'. ':'')+(current.tag?current.tag+'. ':'')+(current.options?current.options.map((o,i)=>`Answer ${i+1}: ${o.split('|').filter(x=>!/^\p{Extended_Pictographic}/u.test(x)&&!['↑','↓','✓','✕','▥'].includes(x)).join(', ')}`).join('. '):current.type==='match'?'Items: '+current.left.join(', ')+'. Places or jobs: '+current.right.join(', '):'Type your answer, then tap Check answer.')}
function home(){stopSpeech();state=null;app.innerHTML=`<section class="hero"><div><div class="eyebrow">The retail skills game show</div><h1>Come on down.<br>It’s <span class="purple">your</span><br><span class="swoosh">time to shine!</span></h1><p>Care for clothes. Help customers. Spin the wheel.<br>Practise your lesson skills, one fun round at a time.</p><div class="hero-actions"><button class="primary" id="start">Let’s play <span aria-hidden="true">↗</span></button><button class="secondary" id="home-how">How to play</button></div><div class="hero-notes"><span>No time limit</span><span>Listen to questions</span><span>Try again</span></div></div><div class="stage-wrap" role="img" aria-label="A game-show stage with a shopping bag, a star podium and a colourful prize wheel"><div class="stage"><div class="spot"></div><div class="spot two"></div><div class="stage-floor"></div><div class="marquee"><small>LET’S PLAY</small>RETAIL<br>SHOWTIME!</div><div class="podium"><div class="price">★ 36</div><span>SHOP SKILL STARS</span></div><div class="bag-art"></div><div class="wheel-stand"></div><div class="art-wheel"></div><div class="art-pointer"></div><span class="spark a">✧</span><span class="spark b">✦</span></div><div class="bubble">A little practice. A big win. ✨</div><div class="bubble bottom">Your next star is waiting! ★</div><span class="spark c">✦</span></div></section><div class="play-path"><strong><span class="step-dot">1</span> Choose an answer</strong><span class="path-arrow">→</span><strong><span class="step-dot">2</span> Collect stars</strong><span class="path-arrow">→</span><strong><span class="step-dot">3</span> Spin to finish!</strong></div><section aria-labelledby="round-title"><div class="section-head"><div><h2 id="round-title">Six rounds. So many ways to play.</h2><p>Choose a topic, or play a show with all six topics.</p></div><span class="small-label">Based on your lessons</span></div><div class="round-grid">${rounds.map((r,i)=>`<button class="round-card" data-round="${i}"><span class="round-icon" style="--tile:${r.color}" aria-hidden="true">${r.icon}</span><span><span class="round-num">Round 0${i+1}</span><h3>${r.name}</h3><p>${r.sub}</p></span><span class="card-arrow" aria-hidden="true">↗</span></button>`).join('')}</div></section>`;bind('start',()=>start());bind('home-how',how);document.querySelectorAll('[data-round]').forEach(b=>b.onclick=()=>start(+b.dataset.round));}
function shuffled(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function start(round=null){initAudio();stopSpeech();outcomes=[];bonus=0;spun=false;spinning=false;const take=prefs.length==='short'?1:prefs.length==='full'?6:3;const queue=round===null?rounds.flatMap((_,r)=>shuffled(bank.map((q,i)=>i).filter(i=>bank[i].r===r)).slice(0,take)):bank.map((q,i)=>i).filter(i=>bank[i].r===round);state={queue,index:0,stars:0,round};showQuestion();goTop()}
function showQuestion(){stopSpeech();current=bank[state.queue[state.index]];selected=[];matched=[];matchLeft=null;wrong=0;usedHint=false;resolved=false;renderQuestion();if(prefs.readAuto)setTimeout(()=>{if(state&&!resolved)read(questionSpeech())},200)}
function renderQuestion(){const q=current,r=rounds[q.r],active=state.queue.slice(0,state.index).map(i=>bank[i].r);app.innerHTML=`<div class="game-top"><button class="back" id="leave">← Back to show</button><div class="score-pill" aria-label="${state.stars} stars">★ <span id="stars">${state.stars}</span> stars</div></div><div class="game-layout"><aside class="game-sidebar" aria-label="Your rounds"><h2>Your show</h2>${rounds.map((v,i)=>`<div class="round-nav ${i===q.r?'active':active.includes(i)?'done':''}"><span class="round-mini" aria-hidden="true">${v.icon}</span><span>${v.name}</span>${i!==q.r&&active.includes(i)?'✓':''}</div>`).join('')}<div class="pace-note">◷ Take your time.<br>There is no timer.<br><br>★ One star for each correct answer.</div></aside><section class="question-panel" aria-labelledby="question-title"><div class="question-meta"><span>${r.icon} ${r.name} · ${state.index+1} of ${state.queue.length}</span><button class="read-btn" id="read">◖♪ Read to me</button></div><div class="progress" role="progressbar" aria-label="Questions completed" aria-valuemin="0" aria-valuemax="${state.queue.length}" aria-valuenow="${state.index}"><span style="width:${state.index/state.queue.length*100}%"></span></div><div class="question-body"><span class="format-label">${formats[q.type]}</span><h1 id="question-title" tabindex="-1">${text(q.title)}</h1><p class="instruction">${text(q.instruction)}</p>${q.product?`<div class="product-display"><span class="product-emoji" aria-hidden="true">${q.symbol==='umbrella'?'<svg viewBox="0 0 100 100" width="94" height="94"><rect x="4" y="4" width="92" height="92" rx="4" fill="none" stroke="currentColor" stroke-width="6"/><path d="M18 46 Q50 8 82 46 Q72 36 62 46 Q50 36 38 46 Q28 36 18 46 M50 26 V74 Q50 89 39 83 Q33 80 36 74" fill="none" stroke="currentColor" stroke-width="6" stroke-linecap="round"/></svg>':q.emoji}</span><div><strong>${text(q.product)}</strong>${q.tag?`<br><span class="price-tag">${text(q.tag)}</span>`:''}</div></div>`:''}<div id="interaction">${interactionHTML(q)}</div><div class="question-tools"><button class="hint-btn" id="hint">☀ Give me a hint</button>${['multi','order','number'].includes(q.type)?'<button class="primary" id="check">Check answer →</button>':''}${q.type==='order'?'<button class="secondary" id="reset-order">Start again</button>':''}</div><div id="hint-area"></div><div id="feedback" aria-live="polite"></div><div id="next-area"></div></div></section></div>`;
 bind('leave',leave);bind('read',()=>read(questionSpeech()));bind('hint',()=>{usedHint=true;$('#hint-area').innerHTML=`<p class="hint-text">☀ ${text(q.hint)}</p>`;say(q.hint);if(prefs.readAuto)read(q.hint)});bind('check',check);bind('reset-order',()=>{if(resolved)return;selected=[];refreshInteraction();$('#feedback').innerHTML=''});bindInteractions();$('#question-title').focus({preventScroll:true});}
function optionLabel(o){const pieces=money(o).split('|');if(pieces.length===1)return esc(pieces[0]);return `<span class="answer-icon" aria-hidden="true">${esc(pieces[0])}</span>${esc(pieces[1])}${pieces[2]?`<br><b>${esc(pieces[2])}</b>`:''}`}
function interactionHTML(q){if(q.type==='choice'||q.type==='multi')return `<div class="choices">${q.options.map((o,i)=>`<button class="choice ${o.includes('|')?'text-choice':''} ${selected.includes(i)?'selected':''}" data-choice="${i}" ${q.type==='multi'?`aria-pressed="${selected.includes(i)}"`:''}>${optionLabel(o)}</button>`).join('')}</div>`;
 if(q.type==='number')return `<label class="number-field"><input id="number-answer" type="number" inputmode="numeric" min="0" step="1" placeholder="?" aria-label="Your answer in ${text(q.unit||'numbers')}" autocomplete="off"><span>${text(q.unit||'')}</span></label>`;
 if(q.type==='match')return `<div class="match-grid"><div class="match-column">${q.left.map((v,i)=>`<button class="match-btn ${matchLeft===i?'selected':''} ${matched.includes(i)?'matched':''}" data-left="${i}" aria-pressed="${matchLeft===i}" ${matched.includes(i)?'disabled':''}>${text(v)}</button>`).join('')}</div><div class="match-column">${q.right.map((v,i)=>`<button class="match-btn ${matched.some(l=>q.answer[l]===i)?'matched':''}" data-right="${i}" ${matched.some(l=>q.answer[l]===i)?'disabled':''}>${text(v)}</button>`).join('')}</div></div>`;
 return `<div class="order-list">${q.options.map((o,i)=>`<button class="order-item ${selected.includes(i)?'selected':''}" data-order="${i}" aria-pressed="${selected.includes(i)}"><span class="order-number">${selected.includes(i)?selected.indexOf(i)+1:'·'}</span><span>${text(o)}</span></button>`).join('')}</div>`}
function refreshInteraction(){$('#interaction').innerHTML=interactionHTML(current);bindInteractions()}
function bindInteractions(){document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(resolved)return;initAudio();const i=+b.dataset.choice;if(current.type==='choice'){selected=[i];evaluate(i===current.answer)}else{if(selected.includes(i))selected=selected.filter(n=>n!==i);else if(selected.length<2)selected.push(i);else{say('Choose two items. Tap a selected item to change it.');return}refreshInteraction()}});document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{if(resolved)return;const i=+b.dataset.order;if(selected.includes(i))selected=selected.filter(n=>n!==i);else selected.push(i);refreshInteraction();say(selected.map((n,i)=>`${i+1}. ${current.options[n]}`).join('. '))});document.querySelectorAll('[data-left]').forEach(b=>b.onclick=()=>{if(resolved)return;matchLeft=+b.dataset.left;refreshInteraction();say(current.left[matchLeft]+'. Now choose a match on the right.');document.querySelector('[data-right]:not(:disabled)')?.focus({preventScroll:true})});document.querySelectorAll('[data-right]').forEach(b=>b.onclick=()=>{if(resolved)return;if(matchLeft===null){say('Tap an item on the left first.');$('#feedback').innerHTML='<div class="hint-text">Tap an item on the left first.</div>';return}const i=+b.dataset.right;if(current.answer[matchLeft]===i){matched.push(matchLeft);matchLeft=null;refreshInteraction();if(matched.length===current.left.length)evaluate(true);else{sfx(true);$('#feedback').innerHTML='<div class="feedback">✓ A match! Find the next pair.</div>';say('A match! Find the next pair.');document.querySelector('[data-left]:not(:disabled)')?.focus({preventScroll:true})}}else evaluate(false)});$('#number-answer')?.addEventListener('keydown',e=>{if(e.key==='Enter')check()})}
function check(){if(resolved)return;initAudio();if(current.type==='number'){const v=$('#number-answer').value;if(v.trim()===''||!Number.isFinite(Number(v))||Number(v)<0){say('Type a number first.');$('#feedback').innerHTML='<div class="hint-text">Type your answer first. Then tap Check answer.</div>';$('#number-answer').focus();return}evaluate(Number(v)===current.answer)}else{const required=current.type==='multi'?2:current.answer.length;if(selected.length!==required){const m=current.type==='multi'?'Pick two answers first.':'Tap all three steps in order first.';say(m);$('#feedback').innerHTML=`<div class="hint-text">${m}</div>`;return}evaluate(current.type==='multi'?selected.every(i=>current.answer.includes(i)):selected.every((n,i)=>n===current.answer[i]))}}
function evaluate(ok){if(resolved)return;stopSpeech();sfx(ok);if(!ok){wrong++;if(wrong<2){$('#feedback').innerHTML=`<div class="feedback retry"><strong>↻ Let’s try again.</strong>${text(current.hint)}</div>`;if(current.type==='choice'){$(`[data-choice="${selected[0]}"]`).classList.add('wrong');$(`[data-choice="${selected[0]}"]`).disabled=true}say('Let’s try again. '+current.hint);if(prefs.readAuto)read('Let’s try again. '+current.hint);return}}
 resolved=true;if(ok){state.stars++;$('#stars').textContent=state.stars}outcomes.push({id:state.queue[state.index],correct:ok,supported:wrong>0||usedHint});if(current.type==='match'&&!ok){matched=current.left.map((_,i)=>i);refreshInteraction()}if(current.type==='order'&&!ok){selected=[...current.answer];refreshInteraction()}document.querySelectorAll('#interaction button,#interaction input,#check,#reset-order').forEach(b=>b.disabled=true);if(current.type==='choice'||current.type==='multi'){const answers=Array.isArray(current.answer)?current.answer:[current.answer];answers.forEach(i=>$(`[data-choice="${i}"]`).classList.add('correct'))}
 const msg=ok?'★ You got it! +1 star':'Let’s learn this one.';$('#feedback').innerHTML=`<div class="feedback ${ok?'':'retry'}"><strong>${msg}</strong>${text(current.explain)}${current.type==='match'?'<ul class="pair-review">'+current.left.map((label,i)=>'<li>'+text(label)+' → '+text(current.right[current.answer[i]])+'</li>').join('')+'</ul>':''}</div>`;$('#next-area').innerHTML=`<div class="next-row"><button class="primary" id="next">${state.index===state.queue.length-1?'Spin the wheel':'Next question'} →</button></div>`;bind('next',()=>{stopSpeech();state.index++;if(state.index>=state.queue.length)showWheel();else showQuestion()});say(msg+' '+current.explain);if(prefs.readAuto)read(msg+'. '+current.explain);$('#next').focus({preventScroll:true});}
function showWheel(){stopSpeech();app.innerHTML=`<section class="finish"><div class="eyebrow" style="justify-content:center">The big finish</div><h1>You’ve earned a spin!</h1><p>Every space is a win.<br>Spin to add 1, 2 or 3 bonus stars.</p><div class="wheel-area"><div class="pointer"></div><div class="bonus-wheel" id="bonus-wheel">${[1,2,3,1,2,3].map((v,i)=>`<span class="wheel-label" style="transform:rotate(${i*60+30}deg)">${v}</span>`).join('')}</div></div><div id="wheel-message" aria-live="polite"></div><button class="primary" id="spin">Spin the wheel ↻</button><p class="micro">You have ${state.stars} question stars.</p></section>`;bind('spin',spin);goTop()}
function spin(){if(spun||spinning)return;spinning=true;initAudio();const segment=Math.floor(Math.random()*6);bonus=[1,2,3,1,2,3][segment];const rotation=5*360+(360-(segment*60+30));$('#spin').disabled=true;$('#spin').textContent='Spinning…';$('#bonus-wheel').style.transform=`rotate(${rotation}deg)`;let ticks=0;const tick=setInterval(()=>{if(prefs.sound&&ctx)tone(560+ticks*12,ctx.currentTime,.06,.04);ticks++;if(ticks>=12)clearInterval(tick)},200);setTimeout(()=>{if(!state)return;spun=true;spinning=false;$('#wheel-message').innerHTML=`<div class="result-score">+${bonus} bonus ${bonus===1?'star':'stars'} ★</div>`;sfx(true);$('#spin').disabled=false;$('#spin').textContent='See my stars →';$('#spin').onclick=finish;say(`You won ${bonus} bonus stars.`)},matchMedia('(prefers-reduced-motion: reduce)').matches?400:3650)}
function finish(){stopSpeech();const first=outcomes.filter(o=>o.correct&&!o.supported).length,supported=outcomes.filter(o=>o.correct&&o.supported).length;app.innerHTML=`<section class="finish"><div class="finish-medal" aria-hidden="true">🏅</div><div class="eyebrow" style="justify-content:center">Show complete</div><h1>Look at you, shop star!</h1><p>You practised ${state.queue.length} shop skills. Well done for taking part.</p><div class="result-score">★ ${state.stars+bonus} stars</div><p class="micro">${state.stars} question stars + ${bonus} wheel stars</p><div class="results-grid"><div class="result-card"><strong>${first}</strong>Correct first try</div><div class="result-card"><strong>${supported}</strong>Correct with help</div><div class="result-card"><strong>${outcomes.length-first-supported}</strong>To practise again</div></div><div class="finish-actions"><button class="primary" id="again">Play again ↻</button><button class="secondary" id="finish-home">Choose a round</button><button class="secondary" id="review">Review answers ↓</button></div><div class="review-list" id="review-list" hidden><h2>Your answers</h2>${outcomes.map((o,i)=>`<details><summary>${o.correct?'★':'↻'} ${i+1}. ${text(bank[o.id].title)}</summary><p>${text(bank[o.id].explain)}</p><p class="micro">${referenceText(bank[o.id])}</p><p class="micro">${o.correct?(o.supported?'Correct with help':'Correct first try'):'Practise again'}</p></details>`).join('')}</div></section>`;const savedRound=state.round;bind('again',()=>start(savedRound));bind('finish-home',()=>{home();goTop()});bind('review',()=>{$('#review-list').hidden=!$('#review-list').hidden;$('#review').textContent=$('#review-list').hidden?'Review answers ↓':'Hide answers ↑';if(!$('#review-list').hidden)$('#review-list').scrollIntoView({behavior:'smooth',block:'start'})});goTop();}
function openDialog(content){stopSpeech();$('#dialog-content').innerHTML=content;$('#dialog').showModal()}
function how(){openDialog(`<h2>Welcome to the show!</h2><p>Play on your own, or take turns as a class.</p><ol><li><strong>Look and listen.</strong><br>Tap “Read to me” to hear a question.</li><li><strong>Have a go.</strong><br>Tap an answer, match items, type a number, or put steps in order.</li><li><strong>Collect stars.</strong><br>A correct answer earns one star. A hint is always okay. You get a second try.</li><li><strong>Spin the wheel!</strong><br>Finish your questions. Win 1, 2 or 3 bonus stars.</li></ol><div class="dialog-note">Take your time. There is no timer.<br>Music starts when you tap “Let’s play”. You can turn it off at the top.</div><br><button class="primary" id="got-it">Got it →</button>`);bind('got-it',()=>$('#dialog').close())}
function referenceText(q){return q.refs.map(ref=>text(sources[ref.source].title)+' · PDF '+(ref.pages.length===1?'page ':'pages ')+ref.pages.join(', ')).join('<br>')}
function settings(){openDialog(`<h2>Teacher settings</h2><p>Questions follow your nine teaching PDFs.</p><label class="setting-row"><span>Show length</span><select id="length"><option value="short">Short show · 6 questions</option><option value="standard">Standard show · 18 questions</option><option value="full">Full show · 36 questions</option></select></label><label class="setting-row"><span>Read questions aloud</span><input id="auto-read" type="checkbox" ${prefs.readAuto?'checked':''}></label><p class="micro">Show length applies to the next game. Each topic round has 6 questions. Short and standard shows choose a fresh mix of questions from every topic.</p><div class="dialog-note"><strong>Classroom tips</strong><br>Read together. Let students point or tap. Give thinking time. Praise effort.<br><br>For tool and steamer practice, follow your teacher’s instructions and the equipment guidance. This game checks knowledge; it does not assess practical competence.<br><br>One star for a correct answer, including a second try. Using a hint is recorded as help. The wheel adds bonus stars separately.<br><br><a href="teacher-guide.html" target="_blank" rel="noopener">View lesson links and question guide ↗</a></div><p class="micro">Read-aloud uses your browser’s voice, when available. Original game inspired by TV game shows. Not affiliated with The Price Is Right.</p><button class="primary" id="save-settings">Save settings ✓</button>`);$('#length').value=prefs.length;bind('save-settings',()=>{prefs.length=$('#length').value;prefs.readAuto=$('#auto-read').checked;delete prefs.short;delete prefs.currency;savePrefs();$('#dialog').close();if(!state)home();say('Settings saved.')})}
function leave(){openDialog('<h2>Leave this show?</h2><p>Your stars from this game will be cleared.</p><div class="finish-actions"><button class="primary" id="keep-playing">Keep playing</button><button class="secondary" id="exit-game">Leave show</button></div>');bind('keep-playing',()=>$('#dialog').close());bind('exit-game',()=>{$('#dialog').close();home();goTop()})}
document.querySelector('.brand').onclick=e=>{e.preventDefault();if(state)leave();else{home();goTop()}};bind('how',how);bind('settings',settings);bind('music',()=>{prefs.music=!prefs.music;savePrefs();initAudio();syncMusic()});bind('sound',()=>{prefs.sound=!prefs.sound;savePrefs();initAudio();if(prefs.sound)sfx(true)});document.querySelector('.dialog-close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close()}});document.addEventListener('visibilitychange',syncMusic);window.addEventListener('pagehide',()=>{if(musicTimer)clearInterval(musicTimer);stopSpeech()});
updateAudioButtons();home();
